-- One row per ISP. The captive portal reads this instead of hardcoded copy.
create table if not exists public.portal_settings (
  isp_id             uuid primary key references public.isps(id) on delete cascade,
  is_enabled         boolean not null default true,
  portal_name        text,
  welcome_message    text,
  terms_conditions   text,
  support_email      text,
  support_phone      text,
  support_whatsapp   text,
  logo_url           text,
  favicon_url        text,
  background_url     text,
  background_color   text,
  primary_color      text,
  accent_color       text,
  login_method       text not null default 'both'
                      check (login_method in ('voucher','customer','both')),
  show_packages      boolean not null default true,
  package_ids        uuid[] not null default '{}',
  payment_instructions text,
  footer_text        text,
  social_links       jsonb not null default '{}'::jsonb,
  hide_routeros      boolean not null default true,
  show_usage         boolean not null default true,
  updated_at         timestamptz not null default now(),
  updated_by         uuid references auth.users(id) on delete set null
);

comment on table public.portal_settings is
  'Per-ISP captive portal branding and copy. The portal renders this; nothing is hardcoded.';

alter table public.portal_settings enable row level security;
alter table public.portal_settings force row level security;

drop policy if exists portal_settings_read on public.portal_settings;
create policy portal_settings_read on public.portal_settings for select
  using (public.is_super_admin() or isp_id = public.current_isp_id());

drop policy if exists portal_settings_write on public.portal_settings;
create policy portal_settings_write on public.portal_settings for insert
  with check (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

drop policy if exists portal_settings_update on public.portal_settings;
create policy portal_settings_update on public.portal_settings for update
  using (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()))
  with check (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

drop policy if exists portal_settings_delete on public.portal_settings;
create policy portal_settings_delete on public.portal_settings for delete
  using (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

