create table if not exists public.network_settings (
  isp_id            uuid primary key references public.isps(id) on delete cascade,
  primary_dns       text,
  secondary_dns     text,
  ntp_server        text,
  session_timeout_min integer not null default 30 check (session_timeout_min between 1 and 1440),
  idle_timeout_min    integer not null default 5  check (idle_timeout_min between 1 and 120),
  keepalive_timeout  text,
  max_sessions      integer check (max_sessions is null or max_sessions > 0),
  radius_enabled    boolean not null default false,
  radius_server     text,
  radius_secret_set boolean not null default false,
  radius_secret_encrypted text,
  auto_renew_enabled boolean not null default true,
  grace_period_days integer not null default 0 check (grace_period_days between 0 and 30),
  updated_at        timestamptz not null default now()
);

comment on column public.network_settings.radius_secret_encrypted is
  'Encrypted in the Edge Function. RLS below exposes no read policy, so staff can never fetch it.';

alter table public.network_settings enable row level security;
alter table public.network_settings force row level security;

drop policy if exists network_settings_read on public.network_settings;
create policy network_settings_read on public.network_settings for select
  using (public.is_super_admin() or isp_id = public.current_isp_id());

drop policy if exists network_settings_write on public.network_settings;
create policy network_settings_write on public.network_settings for insert
  with check (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

drop policy if exists network_settings_update on public.network_settings;
create policy network_settings_update on public.network_settings for update
  using (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()))
  with check (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

-- The Radius secret is readable only by the service role (the Edge Function),
-- which bypasses RLS. Staff must never be able to select this column.
-- -- MikroTik automatic provisioning -----------------------------------------
-- The ISP is never asked for a router IP, username, password or RADIUS secret.
-- Instead we mint a short-lived, single-use token and hand back one RouterOS
-- command. The router itself calls back with that token and we detect what the
-- hardware actually is before sending any configuration.
create table if not exists public.provisioning_sessions (
  id                uuid primary key default gen_random_uuid(),
  isp_id            uuid not null references public.isps(id) on delete cascade,
  node_id           uuid references public.nodes(id) on delete set null,
  label             text not null default 'New router',
  state             text not null default 'created'
                      check (state in ('created','command_generated','command_started',
                                       'router_detected','capabilities_detected',
                                       'waiting_for_selection','configuring','testing',
                                       'online','failed','expired','revoked')),
  role              text not null default 'hotspot'
                      check (role in ('hotspot','pppoe','both')),
  wan_interface     text,
  hotspot_interfaces text[] not null default '{}',
  pppoe_interfaces  text[] not null default '{}',
  -- Everything the router reported about itself, verbatim.
  detected          jsonb not null default '{}'::jsonb,
  capabilities      jsonb not null default '{}'::jsonb,
  wizard_answers    jsonb not null default '{}'::jsonb,
  config_script     text,
  last_error        text,
  attempts          integer not null default 0,
  created_by        uuid references auth.users(id) on delete set null,
  created_at        timestamptz not null default now(),
  detected_at       timestamptz,
  completed_at      timestamptz
);

create index if not exists provisioning_sessions_isp_idx
  on public.provisioning_sessions (isp_id, created_at desc);

alter table public.provisioning_sessions enable row level security;
alter table public.provisioning_sessions force row level security;

drop policy if exists provisioning_sessions_read on public.provisioning_sessions;
create policy provisioning_sessions_read on public.provisioning_sessions for select
  using (public.is_super_admin() or isp_id = public.current_isp_id());

drop policy if exists provisioning_sessions_write on public.provisioning_sessions;
create policy provisioning_sessions_write on public.provisioning_sessions for insert
  with check (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

drop policy if exists provisioning_sessions_update on public.provisioning_sessions;
create policy provisioning_sessions_update on public.provisioning_sessions for update
  using (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()))
  with check (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

drop policy if exists provisioning_sessions_delete on public.provisioning_sessions;
create policy provisioning_sessions_delete on public.provisioning_sessions for delete
  using (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

-- Tokens are hashed at rest; the plaintext exists only in the one command we
-- hand the ISP and is never retrievable afterwards.
create table if not exists public.provisioning_tokens (
  id            uuid primary key default gen_random_uuid(),
  session_id    uuid not null references public.provisioning_sessions(id) on delete cascade,
  isp_id        uuid not null references public.isps(id) on delete cascade,
  token_hash    text not null unique,
  purpose       text not null default 'claim'
                  check (purpose in ('claim','configure','rotate')),
  expires_at    timestamptz not null default (now() + interval '30 minutes'),
  used_at       timestamptz,
  revoked_at    timestamptz,
  created_at    timestamptz not null default now()
);

create index if not exists provisioning_tokens_session_idx
  on public.provisioning_tokens (session_id);
create index if not exists provisioning_tokens_hash_idx
  on public.provisioning_tokens (token_hash);

-- No read policy on purpose: the panel never needs to read a token, it only
-- mints them. The Edge Function looks one up by hash using the service role.
alter table public.provisioning_tokens enable row level security;
alter table public.provisioning_tokens force row level security;

-- -- Provisioning audit -------------------------------------------------------
create table if not exists public.provisioning_events (
  id          bigserial primary key,
  session_id  uuid references public.provisioning_sessions(id) on delete cascade,
  isp_id      uuid not null references public.isps(id) on delete cascade,
  event       text not null,
  detail      jsonb not null default '{}'::jsonb,
  source      text not null default 'panel' check (source in ('panel','router')),
  created_at  timestamptz not null default now()
);

create index if not exists provisioning_events_session_idx
  on public.provisioning_events (session_id, created_at desc);

alter table public.provisioning_events enable row level security;
alter table public.provisioning_events force row level security;

drop policy if exists provisioning_events_read on public.provisioning_events;
create policy provisioning_events_read on public.provisioning_events for select
  using (public.is_super_admin() or isp_id = public.current_isp_id());

-- -- SMS settings -------------------------------------------------------------
create table if not exists public.sms_settings (
  isp_id        uuid primary key references public.isps(id) on delete cascade,
  provider      text not null default 'none'
                  check (provider in ('none','africas_talking','smspro','twilio')),
  sender_id     text,
  account_id    text,
  secret_set    boolean not null default false,
  secret_encrypted text,
  send_on_voucher_purchase boolean not null default true,
  send_on_payment          boolean not null default true,
  send_on_expiry_warning   boolean not null default true,
  expiry_warning_days      integer not null default 3,
  send_on_account_created  boolean not null default false,
  updated_at    timestamptz not null default now()
);

alter table public.sms_settings enable row level security;
alter table public.sms_settings force row level security;

drop policy if exists sms_settings_read on public.sms_settings;
create policy sms_settings_read on public.sms_settings for select
  using (public.is_super_admin() or isp_id = public.current_isp_id());

drop policy if exists sms_settings_write on public.sms_settings;
create policy sms_settings_write on public.sms_settings for insert
  with check (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));

drop policy if exists sms_settings_update on public.sms_settings;
create policy sms_settings_update on public.sms_settings for update
  using (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()))
  with check (public.is_super_admin() or (isp_id = public.current_isp_id() and public.can_manage_isp()));
