-- A tenant owns its Till number. Platform (Daraja) credentials stay in
-- platform_payment_config and are never returned to an ISP. This writes only
-- the tenant's own shortcode and never touches a secret column.
create or replace function public.save_till_settings(p_till text, p_paybill text, p_account text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp uuid := public.current_isp_id();
  v_row public.isp_payment_configs;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  if not (public.is_super_admin() or public.can_manage_isp()) then
    raise exception 'Insufficient permissions';
  end if;

  insert into public.isp_payment_configs (isp_id) values (v_isp)
  on conflict (isp_id) do nothing;

  -- till_number / paybill_number are the tenant's own shortcodes. The Daraja
  -- consumer key, secret and passkey are untouched here and never returned.
  update public.isp_payment_configs t set
    till_number    = nullif(trim(p_till), ''),
    paybill_number = nullif(trim(p_paybill), ''),
    mpesa_shortcode = nullif(trim(p_till), '')
  where t.isp_id = v_isp
  returning * into v_row;

  perform public.log_isp_action('payment:till_saved', 'isp_payment_configs', v_isp::text,
    jsonb_build_object('till', p_till));
  return jsonb_build_object('till', v_row.till_number, 'paybill', v_row.paybill_number);
end;
$$;

grant execute on function public.save_till_settings(text, text, text) to authenticated;

-- Reads a tenant's own till state, non-secret columns only.
create or replace function public.my_till_settings()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'isp_id',          c.isp_id,
    'till_number',     coalesce(c.till_number, c.mpesa_shortcode),
    'paybill_number',  c.paybill_number,
    'customer_notice', c.customer_notice,
    'payment_mode',    coalesce(c.payment_mode, 'manual_till'),
    'mpesa_env',       c.mpesa_env,
    'has_credentials', (c.mpesa_passkey is not null)
  )
  from public.isp_payment_configs c
  where c.isp_id = public.current_isp_id();
$$;

