create or replace function public.save_network_settings(p_patch jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp uuid := public.current_isp_id();
  v_row public.network_settings;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  if not (public.is_super_admin() or public.can_manage_isp()) then
    raise exception 'Insufficient permissions';
  end if;

  insert into public.network_settings (isp_id) values (v_isp)
  on conflict (isp_id) do nothing;

  update public.network_settings t set
    primary_dns         = case when p_patch ? 'primary_dns' then p_patch->>'primary_dns' else t.primary_dns end,
    secondary_dns       = case when p_patch ? 'secondary_dns' then p_patch->>'secondary_dns' else t.secondary_dns end,
    ntp_server          = case when p_patch ? 'ntp_server' then p_patch->>'ntp_server' else t.ntp_server end,
    session_timeout_min = coalesce((p_patch->>'session_timeout_min')::int, t.session_timeout_min),
    idle_timeout_min    = coalesce((p_patch->>'idle_timeout_min')::int, t.idle_timeout_min),
    keepalive_timeout   = case when p_patch ? 'keepalive_timeout' then p_patch->>'keepalive_timeout' else t.keepalive_timeout end,
    max_sessions        = case when p_patch ? 'max_sessions' then (p_patch->>'max_sessions')::int else t.max_sessions end,
    radius_enabled      = coalesce((p_patch->>'radius_enabled')::boolean, t.radius_enabled),
    radius_server       = case when p_patch ? 'radius_server' then p_patch->>'radius_server' else t.radius_server end,
    auto_renew_enabled  = coalesce((p_patch->>'auto_renew_enabled')::boolean, t.auto_renew_enabled),
    grace_period_days   = coalesce((p_patch->>'grace_period_days')::int, t.grace_period_days),
    updated_at          = now()
  where t.isp_id = v_isp
  returning * into v_row;

  perform public.log_isp_action('network:updated', 'network_settings', v_isp::text,
                                jsonb_build_object('isp_id', v_isp));
  -- radius_secret_encrypted is never writable from the client and is stripped
  -- from the response; only the Edge Function can set or read it.
  return to_jsonb(v_row) - 'radius_secret_encrypted';
end;
