create or replace function public.save_sms_settings(p_patch jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp uuid := public.current_isp_id();
  v_row public.sms_settings;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  if not (public.is_super_admin() or public.can_manage_isp()) then
    raise exception 'Insufficient permissions';
  end if;

  insert into public.sms_settings (isp_id) values (v_isp)
  on conflict (isp_id) do nothing;

  update public.sms_settings t set
    provider       = coalesce(p_patch->>'provider', t.provider),
    sender_id      = case when p_patch ? 'sender_id' then p_patch->>'sender_id' else t.sender_id end,
    account_id     = case when p_patch ? 'account_id' then p_patch->>'account_id' else t.account_id end,
    send_on_voucher_purchase = coalesce((p_patch->>'send_on_voucher_purchase')::boolean, t.send_on_voucher_purchase),
    send_on_payment          = coalesce((p_patch->>'send_on_payment')::boolean, t.send_on_payment),
    send_on_expiry_warning   = coalesce((p_patch->>'send_on_expiry_warning')::boolean, t.send_on_expiry_warning),
    expiry_warning_days      = coalesce((p_patch->>'expiry_warning_days')::int, t.expiry_warning_days),
    send_on_account_created  = coalesce((p_patch->>'send_on_account_created')::boolean, t.send_on_account_created),
    updated_at     = now()
  where t.isp_id = v_isp
  returning * into v_row;

  perform public.log_isp_action('sms:settings_updated', 'sms_settings', v_isp::text,
                                jsonb_build_object('provider', v_row.provider));
  return to_jsonb(v_row) - 'secret_encrypted';
end;
$$;

grant execute on function public.save_sms_settings(jsonb) to authenticated;

