-- A `touch_updated_at()` trigger was attached to isp_payment_configs, which has
-- no updated_at column. Any UPDATE on that table therefore failed with
-- `record "new" has no field "updated_at"`, which is what made saving a Till
-- number impossible. The column is added rather than dropping the trigger, so
-- every table that relies on the trigger keeps working.
alter table public.isp_payment_configs
  add column if not exists updated_at timestamptz not null default now();

-- ── Package columns the self-service editor needs ───────────────────────────
-- plans existed before packages were editable from the panel, so FUP,
-- description and portal visibility have to be added rather than assumed.
alter table public.plans
  add column if not exists fup            text,
  add column if not exists description    text,
  add column if not exists show_on_portal boolean not null default true,
  add column if not exists expiry_action  text not null default 'disable'
