Â¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬

-- Mints a session plus a single-use, 30-minute token and returns the one
-- RouterOS command the ISP pastes into the router terminal. The plaintext token
-- is never stored; only its SHA-256 is, so a database leak cannot be replayed.
create or replace function public.create_provisioning_session(
  p_label text,
  p_role  text default 'hotspot'
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp     uuid := public.current_isp_id();
  v_session uuid;
  v_token   text;
  v_hash    text;
  v_expires timestamptz;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  if not (public.is_super_admin() or public.can_manage_isp()) then
    raise exception 'Insufficient permissions';
  end if;
  if p_role not in ('hotspot','pppoe','both') then
    raise exception 'role must be hotspot, pppoe or both';
  end if;

  insert into public.provisioning_sessions (isp_id, label, role, created_by)
  values (v_isp, coalesce(nullif(trim(p_label), ''), 'New router'), p_role, auth.uid())
  returning id into v_session;

  -- pgcrypto is installed into the `extensions` schema on this platform, not
-- public, so the crypto helpers must be schema-qualified. Calling them bare
-- fails inside a security-definer function whose search_path is public.
  v_token   := encode(extensions.gen_random_bytes(16), 'hex');
  v_hash    := encode(extensions.digest(v_token, 'sha256'), 'hex');
  v_expires := now() + interval '30 minutes';

  insert into public.provisioning_tokens (session_id, isp_id, token_hash, expires_at)
  values (v_session, v_isp, v_hash, v_expires);

  insert into public.provisioning_events (session_id, isp_id, event)
  values (v_session, v_isp, 'command_generated');

  update public.provisioning_sessions set state = 'command_generated'
  where id = v_session;

  perform public.log_isp_action('router:provisioning_started', 'provisioning_session',
                                v_session::text, jsonb_build_object('role', p_role));

  return jsonb_build_object(
    'session_id', v_session,
    'token',      v_token,
    'expires_at', v_expires,
    'state',      'command_generated'
  );
end;
$$;

grant execute on function public.create_provisioning_session(text, text) to authenticated;

-- Records the ISP's answers to the setup wizard.
create or replace function public.save_provisioning_answers(
  p_session_id uuid,
  p_answers    jsonb
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp uuid := public.current_isp_id();
  v_row public.provisioning_sessions;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  if not (public.is_super_admin() or public.can_manage_isp()) then
    raise exception 'Insufficient permissions';
  end if;

  update public.provisioning_sessions t set
    role               = coalesce(p_answers->>'role', t.role),
    wan_interface      = nullif(p_answers->>'wan_interface', ''),
    hotspot_interfaces = case
      when jsonb_typeof(p_answers->'hotspot_interfaces') = 'array'
        then array(select jsonb_array_elements_text(p_answers->'hotspot_interfaces'))
      else t.hotspot_interfaces end,
    pppoe_interfaces  = case
      when jsonb_typeof(p_answers->'pppoe_interfaces') = 'array'
        then array(select jsonb_array_elements_text(p_answers->'pppoe_interfaces'))
      else t.pppoe_interfaces end,
    wizard_answers    = t.wizard_answers || coalesce(p_answers, '{}'::jsonb),
    state             = 'configuring',
    last_error        = null
  where t.id = p_session_id and t.isp_id = v_isp
  returning * into v_row;

  if v_row.id is null then raise exception 'Provisioning session not found'; end if;

  insert into public.provisioning_events (session_id, isp_id, event, detail)
  values (p_session_id, v_isp, 'answers_saved', coalesce(p_answers, '{}'::jsonb));

  return jsonb_build_object('session_id', v_row.id, 'state', v_row.state);
end;
$$;

grant execute on function public.save_provisioning_answers(uuid, jsonb) to authenticated;

-- Sweeps expired tokens so an old command stops working.
create or replace function public.expire_provisioning_tokens()
returns integer language plpgsql security definer set search_path = public as $$
declare v_n integer;
begin
  update public.provisioning_tokens
     set revoked_at = now()
   where revoked_at is null and expires_at < now();

  update public.provisioning_sessions s
     set state = 'expired', completed_at = now()
   where s.state in ('created','command_generated','waiting_for_selection')
     and not exists (
       select 1 from public.provisioning_tokens t
       where t.session_id = s.id and t.revoked_at is null
     );

  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

grant execute on function public.expire_provisioning_tokens() to service_role;

-- Revokes a session immediately on the ISP's request.
create or replace function public.revoke_provisioning_session(p_session_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp  uuid := public.current_isp_id();
  v_mark uuid;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  update public.provisioning_tokens set revoked_at = now()
   where session_id = p_session_id and isp_id = v_isp and revoked_at is null;

  update public.provisioning_sessions
     set state = 'revoked', completed_at = now()
   where id = p_session_id and isp_id = v_isp
  returning id into v_mark;
  -- Report honestly. Returning ok:true for a row we never matched would tell
  -- an ISP their revocation succeeded when it silently did nothing, which is
  -- exactly what happens when one tenant passes another tenant's session id.
  if v_mark is null then
    raise exception 'Provisioning session not found';
  end if;

  perform public.log_isp_action('router:provisioning_revoked', 'provisioning_session',
                                p_session_id::text, '{}'::jsonb);
  return jsonb_build_object('ok', true, 'state', 'revoked');
end;
$$;

grant execute on function public.revoke_provisioning_session(uuid) to authenticated;


-- Creates a package for the calling tenant, enforcing the plan's package cap.
create or replace function public.create_plan(p_plan jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp  uuid := public.current_isp_id();
  v_cap  integer;
  v_used integer;
  v_row  uuid;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  if not (public.is_super_admin() or public.can_manage_isp()) then
    raise exception 'Insufficient permissions';
  end if;

  select max_plans into v_cap from public.isps where id = v_isp;
  select count(*) into v_used from public.plans where isp_id = v_isp;

  if v_cap is not null and v_used >= v_cap then
    raise exception 'Your plan allows a maximum of % packages. Upgrade to add more.', v_cap;
  end if;

  insert into public.plans (
    isp_id, name, kind, duration_label, duration_hours, price,
    speed_down, speed_up, data_limit, fup, shared_users,
    description, is_active, is_popular, show_on_portal
  ) values (
    v_isp,
    coalesce(nullif(trim(p_plan->>'name'), ''), 'Unnamed package'),
    coalesce(p_plan->>'kind', 'hotspot'),
    coalesce(nullif(trim(p_plan->>'duration_label'), ''), 'Monthly'),
    coalesce((p_plan->>'duration_hours')::int, 720),
    coalesce((p_plan->>'price')::numeric, 0),
    nullif(p_plan->>'speed_down', ''), nullif(p_plan->>'speed_up', ''),
    nullif(p_plan->>'data_limit', ''), nullif(p_plan->>'fup', ''),
    coalesce((p_plan->>'shared_users')::int, 1),
    nullif(p_plan->>'description', ''),
    coalesce((p_plan->>'is_active')::boolean, true),
    coalesce((p_plan->>'is_popular')::boolean, false),
    coalesce((p_plan->>'show_on_portal')::boolean, true)
  )
  returning id into v_row;

  perform public.log_isp_action('package:created', 'plan', v_row::text,
                                jsonb_build_object('name', p_plan->>'name'));
  return jsonb_build_object('id', v_row);
end;
$$;

grant execute on function public.create_plan(jsonb) to authenticated;

create or replace function public.update_plan(p_plan_id uuid, p_patch jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp uuid := public.current_isp_id();
  v_row public.plans;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  if not (public.is_super_admin() or public.can_manage_isp()) then
    raise exception 'Insufficient permissions';
  end if;

  update public.plans t set
    name           = case when p_patch ? 'name' then p_patch->>'name' else t.name end,
    kind           = case when p_patch ? 'kind' then p_patch->>'kind' else t.kind end,
    duration_label = case when p_patch ? 'duration_label' then p_patch->>'duration_label' else t.duration_label end,
    duration_hours = coalesce((p_patch->>'duration_hours')::int, t.duration_hours),
    price          = coalesce((p_patch->>'price')::numeric, t.price),
    speed_down     = case when p_patch ? 'speed_down' then p_patch->>'speed_down' else t.speed_down end,
    speed_up       = case when p_patch ? 'speed_up' then p_patch->>'speed_up' else t.speed_up end,
    data_limit     = case when p_patch ? 'data_limit' then p_patch->>'data_limit' else t.data_limit end,
    fup            = case when p_patch ? 'fup' then p_patch->>'fup' else t.fup end,
    shared_users   = coalesce((p_patch->>'shared_users')::int, t.shared_users),
    description    = case when p_patch ? 'description' then p_patch->>'description' else t.description end,
    is_active      = coalesce((p_patch->>'is_active')::boolean, t.is_active),
    is_popular     = coalesce((p_patch->>'is_popular')::boolean, t.is_popular),
    show_on_portal = coalesce((p_patch->>'show_on_portal')::boolean, t.show_on_portal),
    updated_at     = now()
  where t.id = p_plan_id and t.isp_id = v_isp
  returning * into v_row;

  if v_row.id is null then raise exception 'Package not found'; end if;

  perform public.log_isp_action('package:updated', 'plan', v_row.id::text,
                                jsonb_build_object('name', v_row.name));
  return jsonb_build_object('id', v_row.id);
end;
$$;

grant execute on function public.update_plan(uuid, jsonb) to authenticated;

-- Refuses to orphan data: customers and vouchers reference packages.
create or replace function public.delete_plan(p_plan_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_isp   uuid := public.current_isp_id();
  v_name  text;
  v_in_use integer;
begin
  if v_isp is null then raise exception 'No ISP in scope'; end if;
  if not (public.is_super_admin() or public.can_manage_isp()) then
    raise exception 'Insufficient permissions';
  end if;

  select name into v_name from public.plans where id = p_plan_id and isp_id = v_isp;
  if v_name is null then raise exception 'Package not found'; end if;

  select (select count(*) from public.vouchers where plan_id = p_plan_id)
       + (select count(*) from public.clients c
            join public.isps i on i.id = c.isp_id
           where c.isp_id = v_isp and c.plan_name = v_name)
    into v_in_use;

  if v_in_use > 0 then
    raise exception 'This package is used by % record(s). Deactivate it instead of deleting.', v_in_use;
  end if;

  delete from public.plans where id = p_plan_id and isp_id = v_isp;

  perform public.log_isp_action('package:deleted', 'plan', p_plan_id::text,
                                jsonb_build_object('name', v_name));
  return jsonb_build_object('ok', true);
end;
$$;

grant execute on function public.delete_plan(uuid) to authenticated;
